// 写路径（延迟双删）
public void write(String key, String value) {
    redis.del(key);              // 先删缓存
    db.update(key, value);       // 再写 DB
    // 延迟 500ms 再删一次，防止读请求在 DB 写入前回填了脏数据
    scheduler.schedule(() -> redis.del(key), 500, MILLISECONDS);
}

public class ShardedCounter {
    private static final int SHARDS = 100;

    public void incr(String key) {
        int shard = ThreadLocalRandom.current().nextInt(SHARDS);
        redis.incr(key + ":" + shard);
    }

    public long get(String key) {
        long total = 0;
        for (int i = 0; i < SHARDS; i++) {
            String v = redis.get(key + ":" + i);
            if (v != null) total += Long.parseLong(v);
        }
        return total;
    }
}

// 1. 缓存穿透：恶意请求不存在的 key
public String getWithPenetration(String key) {
    String v = redis.get(key);
    if (v != null) return v;
    if (!bloomFilter.mightContain(key)) return null;  // 布隆过滤器拦截
    v = db.query(key);
    if (v == null) {
        redis.setex(key, 60, "NULL");  // 缓存空值，短 TTL
        return null;
    }
    redis.setex(key, 300, v);
    return v;
}

