public boolean unlock(String key, String requestId) {
    // Lua 保证"判断+删除"原子性
    String script = "if redis.call('get', KEYS[1]) == ARGV[1] then " +
                    "return redis.call('del', KEYS[1]) else return 0 end";
    return jedis.eval(script, 1, key, requestId).equals(1L);
}

