// 消费端：循环拉取到期任务
public void consume() {
    while (running) {
        long now = System.currentTimeMillis();
        Set<String> tasks = redis.zrangeByScore("delay_queue", 0, now, 0, 1);
        if (tasks.isEmpty()) {
            Thread.sleep(100);
            continue;
        }
        String taskId = tasks.iterator().next();
        // ZREM 返回 1 表示抢到了（原子操作）
        if (redis.zrem("delay_queue", taskId) == 1) {
            processTask(taskId);
        }
    }
}

