public <T> T retryWithBackoff(Supplier<T> task, int maxRetries) {
    int attempt = 0;
    while (true) {
        try {
            return task.get();
        } catch (RetryableException e) {
            attempt++;
            if (attempt >= maxRetries) throw e;
            // 指数退避 + 随机抖动（避免惊群）
            long delayMs = (long) (1000 * Math.pow(2, attempt));
            delayMs += ThreadLocalRandom.current().nextInt(1000);
            Thread.sleep(delayMs);
        }
    }
}

// 找 1 亿个数中最大的 100 个
public List<Long> topK(Iterator<Long> stream, int k) {
    PriorityQueue<Long> heap = new PriorityQueue<>(k);
    while (stream.hasNext()) {
        long num = stream.next();
        if (heap.size() < k) {
            heap.offer(num);
        } else if (num > heap.peek()) {
            heap.poll();
            heap.offer(num);
        }
    }
    return new ArrayList<>(heap);
}

// 1. 分片：把 100GB 切成 100 个 1GB 小文件，分别加载到内存排序
public List<File> splitAndSort(File bigFile, long memoryLimit) {
    List<File> sorted = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(bigFile))) {
        List<String> buffer = new ArrayList<>();
        String line;
        while ((line = reader.readLine()) != null) {
            buffer.add(line);
            if (buffer.size() * 100 > memoryLimit) {  // 假设每行 ~100B
                sorted.add(writeSortToFile(buffer));
                buffer.clear();
            }
        }
        if (!buffer.isEmpty()) sorted.add(writeSortToFile(buffer));
    }
    return sorted;
}

// 2. 归并：k 路归并（用堆维护每个文件的当前行）
public void kWayMerge(List<File> sortedFiles, File output) {
    PriorityQueue<LineIterator> heap = new PriorityQueue<>(
        Comparator.comparing(LineIterator::current));
    // 初始化堆，k 个文件各放一个迭代器
    for (File f : sortedFiles) heap.offer(new LineIterator(f));
    // 不断取堆顶写入输出，迭代器前进
    try (BufferedWriter writer = new BufferedWriter(new FileWriter(output))) {
        while (!heap.isEmpty()) {
            LineIterator it = heap.poll();
            writer.write(it.current() + "\n");
            if (it.hasNext()) { it.next(); heap.offer(it); }
        }
    }
}

// 1. 客户端：计算 MD5，询问服务端是否已存在（秒传）
public String upload(File file) {
    String md5 = md5(file);
    if (server.checkExists(md5)) return server.getFileId(md5);  // 秒传

    // 2. 分片（每片 5MB）
    long chunkSize = 5 * 1024 * 1024;
    int totalChunks = (int) Math.ceil(file.length() / (double) chunkSize);
    String uploadId = server.initUpload(file.getName(), md5, totalChunks);

    // 3. 并行上传（断点续传：已成功的分片跳过）
    Set<Integer> uploaded = server.getUploadedChunks(uploadId);
    ExecutorService pool = Executors.newFixedThreadPool(10);
    for (int i = 0; i < totalChunks; i++) {
        if (uploaded.contains(i)) continue;
        int chunkIdx = i;
        pool.submit(() -> {
            byte[] chunk = readChunk(file, chunkIdx, chunkSize);
            server.uploadChunk(uploadId, chunkIdx, md5(chunk), chunk);
        });
    }
    pool.shutdown();
    pool.awaitTermination(1, TimeUnit.HOURS);

    // 4. 合并分片
    return server.completeUpload(uploadId);
}

public class SnowflakeIdGenerator {
    private static final long EPOCH = 1609459200000L;  // 2021-01-01
    private static final long WORKER_ID_BITS = 10L;     // 支持 1024 个节点
    private static final long SEQUENCE_BITS = 12L;      // 每毫秒 4096 个 ID

    private final long workerId;
    private long sequence = 0L;
    private long lastTimestamp = -1L;

    public synchronized long nextId() {
        long timestamp = System.currentTimeMillis();

        // 时钟回拨检测
        if (timestamp < lastTimestamp) {
            throw new RuntimeException("时钟回拨，拒绝生成 ID");
        }

        if (timestamp == lastTimestamp) {
            // 同一毫秒内递增序列号
            sequence = (sequence + 1) & ((1 << SEQUENCE_BITS) - 1);
            if (sequence == 0) {
                // 序列号用完，等到下一毫秒
                while (timestamp <= lastTimestamp) {
                    timestamp = System.currentTimeMillis();
                }
            }
        } else {
            sequence = 0L;
        }

        lastTimestamp = timestamp;
        return ((timestamp - EPOCH) << (WORKER_ID_BITS + SEQUENCE_BITS))
             | (workerId << SEQUENCE_BITS)
             | sequence;
    }
}

