public class RpcClient {
    private final LoadBalancer lb = new RoundRobinLoadBalancer();
    private final CircuitBreaker breaker = new CircuitBreaker();

    public <T> T call(String service, String method, Object[] args, Class<T> returnType) {
        if (!breaker.allowRequest()) {
            throw new CircuitBreakerOpenException("服务已熔断");
        }

        List<Endpoint> endpoints = lb.choose(service);
        Exception lastException = null;

        for (int i = 0; i < 3; i++) {  // 最多重试 3 次
            Endpoint ep = endpoints.get(i % endpoints.size());
            try {
                return doCall(ep, method, args, returnType, 1000);  // 1s 超时
            } catch (TimeoutException e) {
                lastException = e;
                breaker.recordFailure();
            } catch (Exception e) {
                lastException = e;
                break;  // 非超时异常不重试
            }
        }
        throw new RpcException("调用失败", lastException);
    }
}

public List<Chunk> hybridRetrieve(String query, int topK) {
    // 1. 向量检索（召回 2*topK）
    float[] queryVec = embedding.embed(query);
    List<Chunk> vecResults = vectorDb.search(queryVec, topK * 2);

    // 2. BM25 关键词检索（召回 2*topK）
    List<Chunk> bm25Results = es.search(query, topK * 2);

    // 3. 合并去重（用 RRF 融合）
    Map<String, Double> scores = new HashMap<>();
    int rank = 1;
    for (Chunk c : vecResults) {
        scores.merge(c.id, 1.0 / (60 + rank++), Double::sum);
    }
    rank = 1;
    for (Chunk c : bm25Results) {
        scores.merge(c.id, 1.0 / (60 + rank++), Double::sum);
    }

    // 4. 取 topK 后 Rerank
    List<Chunk> candidates = scores.entrySet().stream()
        .sorted(Map.Entry.<String, Double>comparingByValue().reversed())
        .limit(topK * 2)
        .map(e -> chunkStore.get(e.getKey()))
        .collect(toList());
    return reranker.rerank(query, candidates).subList(0, topK);
}

public class ConversationManager {
    // 会话状态机
    enum State { IDLE, THINKING, STREAMING, INTERRUPTED, COMPLETED }

    public String chat(String sessionId, String userMsg) {
        Conversation conv = store.load(sessionId);

        // 如果是中断恢复，从上次 checkpoint 继续
        if (conv.state == State.INTERRUPTED) {
            return resumeFromCheckpoint(conv);
        }

        // 摘要压缩（如果历史太长）
        if (conv.historyTokens > 8000) {
            conv.summary = llm.summarize(conv.history);
            conv.history = conv.history.subList(-5, 0);  // 只保留最近 5 轮
        }

        conv.history.add(new Message("user", userMsg));
        conv.state = State.THINKING;
        store.save(conv);  // checkpoint

        // 流式生成
        StringBuilder response = new StringBuilder();
        conv.state = State.STREAMING;
        llm.streamChat(conv.history, (token) -> {
            response.append(token);
            conv.partialResponse = response.toString();
            store.saveCheckpoint(conv);  // 每 N 个 token 保存一次
        });

        conv.state = State.COMPLETED;
        conv.history.add(new Message("assistant", response.toString()));
        store.save(conv);
        return response.toString();
    }
}

public class AgentTask {
    private String taskId;
    private int currentStep;
    private List<StepResult> completedSteps;
    private Map<String, Object> context;  // 中间状态

    public void run() {
        // 从 checkpoint 恢复
        Checkpoint cp = checkpointStore.load(taskId);
        if (cp != null) {
            this.currentStep = cp.step;
            this.completedSteps = cp.completedSteps;
            this.context = cp.context;
        }

        Plan plan = planner.plan(goal);
        for (int i = currentStep; i < plan.steps.size(); i++) {
            Step step = plan.steps.get(i);

            // 执行步骤
            StepResult result = executor.execute(step, context);
            completedSteps.add(result);
            context.put(step.outputKey, result.output);

            // 每步保存 checkpoint
            checkpointStore.save(new Checkpoint(taskId, i + 1, completedSteps, context));
        }
    }
}
